text:
{
  "design": {
    "theme": "crayon",
    "picture_style": "illustration"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall sharing equally",
      "look_at": {
        "kind": "picture",
        "shows": "Two plates with different numbers of strawberries"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the learning objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach halves and quarters of shapes",
      "look_at": {
        "kind": "diagram",
        "shows": "One of two equal parts and one of four equal parts shaded"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Identify shaded fractions",
      "look_at": {
        "kind": "diagram",
        "shows": "New shapes split into two or four equal parts"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Correct the unequal-parts misconception",
      "look_at": {
        "kind": "diagram",
        "shows": "Equal halves beside two unequal pieces"
      },
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Model finding half of an amount",
      "look_at": {
        "kind": "diagram",
        "shows": "Twelve counters shared into two equal groups"
      },
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Practise finding half by sharing",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Model finding a quarter of an amount",
      "look_at": {
        "kind": "diagram",
        "shows": "Twelve counters shared into four equal groups"
      },
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Practise finding a quarter by sharing",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Check which groups show a quarter",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Choose and use the right sharing method",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2, 3]
    },
    {
      "slide": 12,
      "does": "Apply fractions to new problems",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Halves and quarters",
    "lead": "Are these shares equal? Explain.",
    "picture": {
      "shows": "Two identical plates, one holding two strawberries and the other holding four",
      "must_see": [
        "two matching plates",
        "two strawberries",
        "four strawberries"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Equal parts",
      "lead": "Equal parts are the same size.",
      "points": [
        {
          "label": "Half",
          "text": "One of two equal parts."
        },
        {
          "label": "Quarter",
          "text": "One of four equal parts."
        }
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "A half and a quarter of matching rectangles",
        "alt": "Two matching rectangles: one has one of two equal parts shaded; the other has one of four equal parts shaded.",
        "title": null,
        "shapes": [
          {
            "shape": "rectangle",
            "parts": 2,
            "cut": "vertical",
            "shaded": 1,
            "name": "½"
          },
          {
            "shape": "rectangle",
            "parts": 4,
            "cut": "vertical",
            "shaded": 1,
            "name": "¼"
          }
        ]
      }
    },
    {
      "template": "big-visual",
      "heading": "Name the shaded part",
      "lead": "Say half or quarter for A and B. Explain why.",
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Two shapes for pupils to identify by their equal parts",
        "alt": "Shape A is a circle with one of four equal parts shaded. Shape B is a square with one of two equal parts shaded.",
        "title": null,
        "shapes": [
          {
            "shape": "circle",
            "parts": 4,
            "cut": "auto",
            "shaded": 1,
            "name": "A"
          },
          {
            "shape": "square",
            "parts": 2,
            "cut": "diagonal",
            "shaded": 1,
            "name": "B"
          }
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Two pieces are not always halves",
      "lead": "Halves must be equal in size.",
      "points": [
        "A shows halves: the parts match.",
        "B has two unequal pieces."
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "Two identical rectangles side by side. A is split vertically into two equal parts with one shaded. B is split vertically into a narrow part and a wide part, with the narrow part shaded. Make the unequal sizes unmistakable.",
        "labels": ["A", "B"]
      }
    },
    {
      "template": "steps",
      "heading": "Find half of 12",
      "points": [
        "Share 12 counters into two groups.",
        "Make both groups equal.",
        "Count one group: half of 12 is 6."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared into two equal groups of six",
        "alt": "Twelve counters in two rings, with six counters in each ring.",
        "title": null,
        "total": 12,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "practice",
      "heading": "Find half",
      "questions": [
        "Find half of 16 counters.",
        "Find half of 10 counters.",
        "Find half of 20 counters."
      ],
      "instruction": "Draw two groups. Share equally. Count one group.",
      "picture": null
    },
    {
      "template": "steps",
      "heading": "Find a quarter of 12",
      "points": [
        "Share 12 counters into four groups.",
        "Make all four groups equal.",
        "Count one group: a quarter of 12 is 3."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared into four equal groups of three",
        "alt": "Twelve counters in four rings, with three counters in each ring.",
        "title": null,
        "total": 12,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "practice",
      "heading": "Find a quarter",
      "questions": [
        "Find a quarter of 16 counters.",
        "Find a quarter of 8 counters.",
        "Find a quarter of 4 counters."
      ],
      "instruction": "Draw four groups. Share equally. Count one group.",
      "picture": null
    },
    {
      "template": "hinge",
      "heading": "Choose the sharing",
      "stem": "Which sharing finds a quarter of 20?",
      "options": [
        "Two groups of 10",
        "Four groups of 5",
        "Five groups of 4"
      ],
      "correct": 2
    },
    {
      "template": "practice",
      "heading": "Choose your groups",
      "questions": [
        "Find half of 18 buttons.",
        "Find a quarter of 20 buttons.",
        "Find half and a quarter of 8 buttons."
      ],
      "instruction": "Draw equal groups. Write each answer.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Solve the problems",
      "questions": [
        "Draw a square. Split it into quarters. Shade one.",
        "Half of 14 birds fly away. How many stay?",
        "A quarter of 20 beads are red. How many are not red?"
      ],
      "instruction": "Draw to show your thinking.",
      "picture": null
    }
  ]
}
